function Alumni(){
  const years=Object.keys(ALUMNI).sort((a,b)=>Number(a)-Number(b));
  const [year,setYear]=React.useState(years.length?years[years.length-1]:'2064');
  const rows=Array.isArray(ALUMNI[year])?ALUMNI[year]:[];
  const cell=r=>Array.isArray(r)?r:[r.sno,r.name,r.om,r.percentage,r.division,r.gpa,r.grade,r.year];
  const grid=e('div',{className:'alumni-year-grid'},years.map(y=>e('button',{key:y,className:y===year?'active':'',onClick:()=>setYear(y)},y+' B.S.')));
  const head=e('thead',null,e('tr',null,['S.No','Name','OM','Percentage','Division','GPA','Grade','Year'].map(h=>e('th',{key:h},h))));
  const body=e('tbody',null,rows.map((r,i)=>e('tr',{key:i},cell(r).map((v,j)=>e('td',{key:j},v==null?'':String(v))))));
  const table=e('div',{className:'alumni-table-wrap'},e('table',null,head,body));
  return e('div',{className:'alumni-spa-wrap'},grid,e('div',{className:'alumni-toolbar'},e('h2',null,'Class of ',year,' B.S.'),e('button',{className:'see-all-btn',onClick:()=>table.props},'See All')),table);
}

